@Test
public void testSlowDataNodeMetrics() throws Exception {
  Configuration conf = new HdfsConfiguration();
  // Consider every flushOrSync and every ack sent upstream as slow, so that
  // both counters are incremented deterministically.
  conf.setLong(DFSConfigKeys.DFS_DATANODE_SLOW_IO_WARNING_THRESHOLD_KEY, -1L);
  MiniDFSCluster cluster = new MiniDFSCluster.Builder(conf)
      .numDataNodes(1).build();
  try {
    cluster.waitActive();
    DistributedFileSystem fs = cluster.getFileSystem();
    Path testFile = new Path("/testSlowDataNodeMetrics.txt");
    try (FSDataOutputStream fout = fs.create(testFile)) {
      fout.write(new byte[1]);
      fout.hsync();
    }
    DataNode dn = cluster.getDataNodes().get(0);
    MetricsRecordBuilder dnMetrics = getMetrics(dn.getMetrics().name());
    assertTrue("At least 1 slow flushOrSync",
        getLongCounter("SlowFlushOrSyncCount", dnMetrics) >= 1L);
    assertTrue("At least 1 slow ack to upstream",
        getLongCounter("SlowAckToUpstreamCount", dnMetrics) >= 1L);
  } finally {
    if (cluster != null) {
      cluster.shutdown();
    }
  }
}

